code = '''from collections import Counter


def _runs(indices):
    if not indices:
        return []
    out = []
    start = prev = indices[0]
    for x in indices[1:]:
        if x != prev + 1:
            out.append((start, prev + 1))
            start = x
        prev = x
    out.append((start, prev + 1))
    return out


def transform(grid):
    h, w = len(grid), len(grid[0])
    row_bands = _runs([r for r in range(h) if any(grid[r])])
    col_bands = _runs([c for c in range(w) if any(grid[r][c] for r in range(h))])

    tiles = [[grid[r0:r1] for c0, c1 in col_bands for r0, r1 in []]]  # replaced below
    blocks = []
    dominant = []
    for r0, r1 in row_bands:
        row = []
        for c0, c1 in col_bands:
            vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0]
            row.append(vals)
            if vals:
                dominant.append(Counter(vals).most_common(1)[0][0])
        blocks.append(row)
    base = Counter(dominant).most_common(1)[0][0]

    colors = [[None for _ in col_bands] for _ in row_bands]
    masks = [[set() for _ in col_bands] for _ in row_bands]
    for i, (r0, r1) in enumerate(row_bands):
        for j, (c0, c1) in enumerate(col_bands):
            vals = [v for v in blocks[i][j] if v != base]
            if not vals:
                continue
            color = Counter(vals).most_common(1)[0][0]
            colors[i][j] = color
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] == color:
                        masks[i][j].add((r-r0, c-c0))

    out = [row[:] for row in grid]
    # Join matching tiles along each tile row, filling only the blank bands between tiles.
    for i, (r0, r1) in enumerate(row_bands):
        for left in range(len(col_bands)):
            color = colors[i][left]
            if color is None:
                continue
            for right in range(left + 1, len(col_bands)):
                if colors[i][right] != color:
                    continue
                common_rows = {dr for dr, _ in masks[i][left]} & {dr for dr, _ in masks[i][right]}
                for dr in common_rows:
                    y = r0 + dr
                    for k in range(left, right):
                        for x in range(col_bands[k][1], col_bands[k+1][0]):
                            if 0 <= y < h and 0 <= x < w:
                                out[y][x] = color

    # Join matching tiles along each tile column.
    for j, (c0, c1) in enumerate(col_bands):
        for top in range(len(row_bands)):
            color = colors[top][j]
            if color is None:
                continue
            for bottom in range(top + 1, len(row_bands)):
                if colors[bottom][j] != color:
                    continue
                common_cols = {dc for _, dc in masks[top][j]} & {dc for _, dc in masks[bottom][j]}
                for dc in common_cols:
                    x = c0 + dc
                    for k in range(top, bottom):
                        for y in range(row_bands[k][1], row_bands[k+1][0]):
                            if 0 <= y < h and 0 <= x < w:
                                out[y][x] = color
    return out
'''
